document.addEventListener('click', function(e) {
  const target = e.target && e.target.closest('a');
  if (target) {
    const href = target.href;
    if (href && href.startsWith('javascript:')) {
      e.preventDefault();
      e.stopPropagation();
    }
  }
}, true);
